    CASE(OP_GT, B) {
      OP_CMP(>,gt);
      NEXT;
    }

    CASE(OP_GE, B) {
      OP_CMP(>=,ge);
      NEXT;
    }

    CASE(OP_ARRAY, BB) {
      regs[a] = ary_new_from_regs(mrb, b, a);
      mrb_gc_arena_restore(mrb, ai);
      NEXT;
    }
    CASE(OP_ARRAY2, BBB) {
      regs[a] = ary_new_from_regs(mrb, c, b);
      mrb_gc_arena_restore(mrb, ai);
      NEXT;
    }

    CASE(OP_ARYCAT, B) {
      if (mrb_respond_to(mrb, regs[a+1], MRB_SYM(to_a)) && (mrb->c->ci + 1 >= mrb->c->ciend)) {
        fprintf(stderr, "ASSERT_EVT point=arycat_pre_splat local_ci=%p\n", (void *)ci);
      }
      mrb_value splat = mrb_ary_splat(mrb, regs[a+1]);
      ci = mrb->c->ci;
      if (assert_ci_realloc_seen) {
        fprintf(stderr,
                "ASSERT_EVT point=arycat_post_splat local_ci=%p current_ci=%p\n",
                (void *)ci, (void *)mrb->c->ci);
        fprintf(stderr, "ASSERT_EVT point=arycat_sink local_ci=%p\n", (void *)ci);
        assert_ci_realloc_seen = 0;
      }
      if (mrb_nil_p(regs[a])) {
        regs[a] = splat;
      }
      else {
        mrb_assert(mrb_array_p(regs[a]));
        mrb_ary_concat(mrb, regs[a], splat);
      }
      mrb_gc_arena_restore(mrb, ai);
      NEXT;
    }

    CASE(OP_ARYPUSH, BB) {
      mrb_assert(mrb_array_p(regs[a]));
      for (mrb_int i=0; i<b; i++) {
        mrb_ary_push(mrb, regs[a], regs[a+i+1]);
      }
      NEXT;
    }

    CASE(OP_ARYSPLAT, B) {
      mrb_value ary = mrb_ary_splat(mrb, regs[a]);
      ci = mrb->c->ci;
      regs[a] = ary;
      mrb_gc_arena_restore(mrb, ai);
      NEXT;
    }

    CASE(OP_AREF, BBB) {
      mrb_value v = regs[b];

      if (!mrb_array_p(v)) {
        if (c == 0) {
          regs[a] = v;
        }
        else {
          SET_NIL_VALUE(regs[a]);
        }
      }
      else {
        v = mrb_ary_ref(mrb, v, c);
        regs[a] = v;
      }
      NEXT;
    }
